import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { createMeeting, getStaff } from '../api';

function CreateMeeting() {
  const navigate = useNavigate();
  const [staff, setStaff] = useState([]);
  const [form, setForm] = useState({
    title: '',
    description: '',
    date: '',
    time: '',
    venue: '',
    agenda: '',
    attendees: []  // list of selected staff IDs
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // Load staff list to pick attendees
  useEffect(() => {
    const loadStaff = async () => {
      try {
        const res = await getStaff();
        setStaff(res.data);
      } catch (err) {
        console.error('Error loading staff');
      }
    };
    loadStaff();
  }, []);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  // Toggle attendee selection (checkbox behaviour)
  const toggleAttendee = (id) => {
    if (form.attendees.includes(id)) {
      setForm({ ...form, attendees: form.attendees.filter(a => a !== id) });
    } else {
      setForm({ ...form, attendees: [...form.attendees, id] });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      await createMeeting(form);
      alert('Meeting created successfully!');
      navigate('/meetings');
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to create meeting');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="page">
      <h1>📅 Schedule New Meeting</h1>

      <div className="card">
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Meeting Title *</label>
            <input
              type="text"
              name="title"
              placeholder="e.g. Department Monthly Review"
              value={form.title}
              onChange={handleChange}
              required
            />
          </div>

          <div className="form-group">
            <label>Description</label>
            <textarea
              name="description"
              placeholder="Brief description of the meeting..."
              value={form.description}
              onChange={handleChange}
              rows="2"
            />
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
            <div className="form-group">
              <label>Date *</label>
              <input
                type="date"
                name="date"
                value={form.date}
                onChange={handleChange}
                required
              />
            </div>

            <div className="form-group">
              <label>Time *</label>
              <input
                type="time"
                name="time"
                value={form.time}
                onChange={handleChange}
                required
              />
            </div>
          </div>

          <div className="form-group">
            <label>Venue *</label>
            <input
              type="text"
              name="venue"
              placeholder="e.g. Conference Room A, Block 2"
              value={form.venue}
              onChange={handleChange}
              required
            />
          </div>

          <div className="form-group">
            <label>Agenda / Topics to Discuss</label>
            <textarea
              name="agenda"
              placeholder="1. Exam schedule review&#10;2. Student feedback&#10;3. Lab updates"
              value={form.agenda}
              onChange={handleChange}
              rows="4"
            />
          </div>

          {/* Staff Selection */}
          <div className="form-group">
            <label>Select Attendees ({form.attendees.length} selected)</label>
            <div style={{
              border: '1px solid #d1d5db',
              borderRadius: '8px',
              maxHeight: '200px',
              overflowY: 'auto',
              padding: '0.5rem'
            }}>
              {staff.length === 0 ? (
                <p style={{ color: '#64748b', padding: '0.5rem' }}>No staff members found. Register some staff accounts first.</p>
              ) : (
                staff.map(member => (
                  <label
                    key={member._id}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: '0.5rem',
                      padding: '0.5rem',
                      borderRadius: '6px',
                      cursor: 'pointer',
                      background: form.attendees.includes(member._id) ? '#eff6ff' : 'white'
                    }}
                  >
                    <input
                      type="checkbox"
                      checked={form.attendees.includes(member._id)}
                      onChange={() => toggleAttendee(member._id)}
                    />
                    <span>{member.name}</span>
                    <span style={{ color: '#64748b', fontSize: '0.8rem' }}>{member.email}</span>
                    <span style={{
                      marginLeft: 'auto',
                      background: member.role === 'admin' ? '#ede9fe' : '#dcfce7',
                      color: member.role === 'admin' ? '#7c3aed' : '#166534',
                      padding: '1px 8px',
                      borderRadius: '10px',
                      fontSize: '0.75rem'
                    }}>
                      {member.role}
                    </span>
                  </label>
                ))
              )}
            </div>
          </div>

          {error && <p className="error">{error}</p>}

          <div style={{ display: 'flex', gap: '1rem', marginTop: '1rem' }}>
            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? 'Creating...' : '✅ Create Meeting'}
            </button>
            <button type="button" className="btn btn-gray" onClick={() => navigate('/meetings')}>
              Cancel
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export default CreateMeeting;
